import React, { useEffect, useState, useRef } from 'react';
import { generateKeys, encryptMessage, decryptMessage, storePrivateKey, retrievePrivateKey } from '../utils/crypto';

const Chat = () => {
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState('');
  const [ws, setWs] = useState(null);
  const [keys, setKeys] = useState({ publicKey: null, recipientPublicKey: null });

  const privateKeyRef = useRef(null); // Инициализация useRef для хранения приватного ключа

  useEffect(() => {
    const initChat = async () => {
      try {
        if (ws) {
          console.log('WebSocket уже подключен');
          return; // Избегаем повторного создания WebSocket
        }
        const socket = new WebSocket('ws://localhost:8080');
        setWs(socket);
        console.log('WebSocket инициализируется...');

        let privateKey = await retrievePrivateKey();
        if (!privateKey) {
          const { privateKey: generatedPrivateKey, publicKey } = await generateKeys();
          privateKey = keys.privateKey;
          publicKey = keys.publicKey;
          await storePrivateKey(privateKey);
        } else {
          const keys = await generateKeys();
          publicKey = keys.publicKey;
        }

        privateKeyRef.current = privateKey;
        setKeys({ publicKey, recipientPublicKey: null });

        socket.onopen = () => {
          console.log('WebSocket connected');
          console.log('Отправляем данные на сервер:', {
            type: 'key_exchange',
            publicKey: keys.publicKey,
          });
          if (!keys.publicKey) {
            console.error('Ключи не были сгенерированы. Проверьте метод generateKeys()');
          }
          // Отправляем публичный ключ
          // Генерация ключей и отправка публичного ключа
          if (keys.publicKey) {
            socket.send(
              JSON.stringify({
                type: 'key_exchange',
                publicKey: keys.publicKey, // Отправляем публичный ключ
              })
            );
            console.log('Публичный ключ отправлен на сервер');
          } else {
            console.error('Публичный ключ не найден');
          }
        };

        socket.onmessage = async (event) => {
          const data = JSON.parse(event.data);
          console.log('Получено сообщение от сервера:', data);

          if (data.type === 'key_exchange') {
            console.log('Получен публичный ключ:', data.publicKey);
            // Устанавливаем публичный ключ получателя
            setKeys((prevKeys) => ({ ...prevKeys, recipientPublicKey: data.publicKey }));
          } else if (data.type === 'info') {
            console.log(data.message); // Лог информационных сообщений
          } else if (data.type === 'message') {
            try {
              const decryptedMessage = await decryptMessage(data.encryptedMessage, privateKeyRef.current);
              setMessages((prev) => [...prev, { userId: data.userId, text: decryptedMessage }]);
            } catch (err) {
              console.error('Ошибка расшифровки сообщения:', err);
            }
          }
        };

        socket.onerror = (err) => {
          console.error('WebSocket error:', err);
        };

        socket.onclose = () => {
          console.log('WebSocket connection closed');
        };
      } catch (err) {
        console.error('Ошибка инициализации чата:', err);
      }
    };

    initChat();
  }, [ws]);


  const sendMessage = async (message) => {
    if (!ws || ws.readyState !== WebSocket.OPEN) {
      console.error('WebSocket is not connected');
      return;
    }

    if (!keys.recipientPublicKey) {
      console.error("Recipient's public key is missing");
      return;
    }

    try {
      const encryptedMessage = await encryptMessage(message, keys.recipientPublicKey);
      ws.send(JSON.stringify({ type: 'message', encryptedMessage }));

      setMessages((prev) => [...prev, { userId: 'You', text: message }]);
      setInput('');
    } catch (err) {
      console.error('Ошибка отправки сообщения:', err);
    }
  };

  return (
    <div>
      <h1>Anonymous Chat</h1>
      {!keys.recipientPublicKey && (
        <p style={{ color: 'red' }}>
          Ожидание публичного ключа другого клиента. Подключите второго клиента для начала общения.
        </p>
      )}
      <div>
        {messages.map((msg, index) => (
          <p key={index}>
            <strong>{msg.userId}:</strong> {msg.text}
          </p>
        ))}
      </div>
      <input
        type="text"
        value={input}
        onChange={(e) => setInput(e.target.value)}
        placeholder="Введите сообщение..."
      />
      <button onClick={() => sendMessage(input)} disabled={!keys.recipientPublicKey}>
        Отправить
      </button>
    </div>
  );
};

export default Chat;
